using System.Collections.Generic;

namespace Cascade.Presentation
{
    public sealed partial class CascadeGame
    {
        static readonly Dictionary<string,string[]> collectionStories=new Dictionary<string,string[]>
        {
            {"leaf",new[]{"A symbol of luck.\nHelps you find rare rewards\nwhen the path gets difficult.","Символ удачи.\nПомогает находить редкие награды\nв трудных ситуациях.","Символ удачі.\nДопомагає знаходити рідкісні нагороди\nу складних ситуаціях."}},
            {"sun",new[]{"A symbol of a clear path.\nHelps you find the right answer\nwhen the way gets difficult.","Символ ясного пути.\nПомогает находить верные решения\nв трудных ситуациях.","Символ ясного шляху.\nДопомагає знаходити правильні рішення\nу складних ситуаціях."}},
            {"sky",new[]{"A little piece of sky.\nFor messengers who carry good news\nfrom island to island.","Частичка неба.\nДля тех, кто несёт добрые вести\nс острова на остров.","Частинка неба.\nДля тих, хто несе добрі звістки\nз острова на острів."}},
            {"moon",new[]{"A pocketful of moonlight.\nEven the longest evening\ncan end with a bright discovery.","Лунный свет в кармане.\nДаже самый долгий вечер\nможет закончиться открытием.","Місячне світло в кишені.\nНавіть найдовший вечір\nможе завершитися відкриттям."}},
            {"wind_chime",new[]{"A symbol of a clear path.\nHelps you find the right answer\nwhen the way gets difficult.","Символ ясного пути.\nПомогает находить верные решения\nв трудных ситуациях.","Символ ясного шляху.\nДопомагає знаходити правильні рішення\nу складних ситуаціях."}},
            {"rain_badge",new[]{"A friend on rainy days.\nRain taps on Mika’s coat;\nher lantern stays warm.","Друг дождливых дней.\nКапли стучат по плащу Мики,\nа фонарь всё так же греет.","Друг дощових днів.\nКраплі стукають по плащу Міки,\nа ліхтар усе так само гріє."}},
            {"copper_acorn",new[]{"A promise of tomorrow.\nA tiny acorn remembers\na tree that has yet to grow.","Обещание завтрашнего дня.\nМаленький жёлудь хранит мечту\nо большом дереве.","Обіцянка завтрашнього дня.\nМаленький жолудь береже мрію\nпро велике дерево."}},
            {"beacon_brooch",new[]{"A light for the way home.\nFireflies gather around it,\nlike friends at the garden gate.","Огонёк для дороги домой.\nСветлячки собираются рядом,\nбудто друзья у калитки.","Вогник для дороги додому.\nСвітлячки збираються поруч,\nначе друзі біля хвіртки."}},
            {"sky_pilot",new[]{"A hat for brave flights.\nThe wind knows Mika by name\nand brings feathers as greetings.","Шапка для смелых полётов.\nВетер знает Мику по имени\nи передаёт приветы перьями.","Шапка для сміливих польотів.\nВітер знає Міку на ім’я\nі передає привіти пір’їнками."}},
            {"moth_mask",new[]{"A guest of the evening.\nIn this mask, Mika can almost\nhear the stars whisper.","Гостья вечернего сада.\nВ этой маске Мика почти слышит,\nкак шепчутся звёзды.","Гостя вечірнього саду.\nУ цій масці Міка майже чує,\nяк шепочуться зорі."}},
            {"garden_festival",new[]{"A garden celebration.\nPetals dance around Mika\nlike confetti made by spring.","Праздник в саду.\nЛепестки кружатся вокруг Мики —\nсама весна придумала конфетти.","Свято в саду.\nПелюстки кружляють навколо Міки —\nсама весна вигадала конфеті."}},
            {"cloud_gardener",new[]{"A gardener of the sky.\nMika tends the little islands\nand greets each leaf by name.","Садовница небес.\nМика заботится об островках\nи здоровается с каждым листочком.","Садівниця небес.\nМіка дбає про острівці\nй вітається з кожним листочком."}},
            {"explorer_hat",new[]{"A hat full of plans.\nThere is always room underneath\nfor one more curious question.","Шляпа, полная планов.\nПод ней всегда найдётся место\nдля ещё одного любопытного вопроса.","Капелюх, повний планів.\nПід ним завжди знайдеться місце\nдля ще одного цікавого запитання."}},
            {"frog_suit",new[]{"A cheerful rainy-day hood.\nMika looks ready to greet\nevery frog beside the puddles.","Весёлый капюшон для дождя.\nМика готова поздороваться\nсо всеми лягушками у луж.","Веселий каптур для дощу.\nМіка готова привітатися\nз усіма жабками біля калюж."}},
            {"star_knight",new[]{"A cape for a kind knight.\nMika’s favourite brave deed\nis helping a friend get home.","Плащ доброго рыцаря.\nЛюбимый подвиг Мики —\nпомочь другу вернуться домой.","Плащ доброго лицаря.\nУлюблений подвиг Міки —\nдопомогти другові повернутися додому."}},
            {"fox_mask",new[]{"A little woodland secret.\nMika smiles behind the mask;\nthe petals know it is still her.","Маленькая лесная тайна.\nМика улыбается под маской,\nа лепестки всё равно её узнают.","Маленька лісова таємниця.\nМіка усміхається під маскою,\nа пелюстки все одно її впізнають."}},
            {"mushroom_cap",new[]{"A hat from the forest.\nPerhaps there is a tiny story\nhiding beneath every mushroom.","Шляпа из леса.\nНаверное, под каждым грибом\nпрячется маленькая история.","Капелюх із лісу.\nМабуть, під кожним грибом\nховається маленька історія."}},
            {"bee_suit",new[]{"A sunny little worker.\nMika carries garden warmth\nas carefully as a bee carries pollen.","Солнечная труженица.\nМика бережёт тепло сада,\nкак пчёлка бережёт пыльцу.","Сонячна трудівниця.\nМіка береже тепло саду,\nяк бджілка береже пилок."}},
            {"winter_hood",new[]{"Warmth for a snowy walk.\nSnowflakes land on Mika’s hood\nand listen to her next story.","Тепло для снежной прогулки.\nСнежинки садятся на капюшон\nи слушают новую историю Мики.","Тепло для сніжної прогулянки.\nСніжинки сідають на каптур\nі слухають нову історію Міки."}},
            {"pirate_hat",new[]{"A captain of the clouds.\nMika’s treasure map has\na warm welcome at every harbour.","Капитан облаков.\nНа карте сокровищ Мики\nв каждой гавани ждут друзья.","Капітанка хмар.\nНа мапі скарбів Міки\nв кожній гавані чекають друзі."}},
            {"jester_suit",new[]{"A pocketful of laughter.\nMika only needs one funny bow\nto make a gloomy day smile.","Карман, полный смеха.\nОдин смешной поклон Мики —\nи хмурый день уже улыбается.","Кишеня, повна сміху.\nОдин кумедний уклін Міки —\nі похмурий день уже усміхається."}},
            {"constellation_mage",new[]{"A cloak of starry stories.\nMika joins the little lights\nand gives each constellation a name.","Плащ звёздных историй.\nМика соединяет огоньки\nи придумывает созвездиям имена.","Плащ зоряних історій.\nМіка з’єднує вогники\nй вигадує сузір’ям імена."}},
            {"paper_crane",new[]{"A carefully folded wish.\nThis little crane reminds Mika\nthat gentle things can travel far.","Бережно сложенная мечта.\nБумажный журавлик напоминает:\nдаже хрупкие вещи умеют летать.","Дбайливо складена мрія.\nПаперовий журавлик нагадує:\nнавіть тендітні речі вміють літати."}},
            {"tiny_comet",new[]{"A greeting from the stars.\nA little comet passed by\nand left Mika this bright keepsake.","Привет от звёзд.\nМаленькая комета пролетела мимо\nи оставила Мике подарок.","Привіт від зірок.\nМаленька комета пролетіла повз\nі залишила Міці подарунок."}},
            {"dew_bell",new[]{"A bell for quiet mornings.\nIt holds a drop of dew\nand the garden’s first soft greeting.","Колокольчик тихого утра.\nВ нём живут капелька росы\nи первый нежный привет сада.","Дзвіночок тихого ранку.\nУ ньому живуть краплинка роси\nй перше ніжне вітання саду."}},
            {"night_flower",new[]{"A flower that waits for dusk.\nIts little glow tells Mika:\nthe garden is awake with her.","Цветок, который ждёт сумерек.\nЕго огонёк говорит Мике:\nсад ещё не спит.","Квітка, що чекає сутінків.\nЇї вогник каже Міці:\nсад іще не спить."}},
            {"cloud_kite",new[]{"A kite with a cloud’s heart.\nMika keeps its tiny ribbon\nas a memory of a windy afternoon.","Воздушный змей с душой облака.\nМика хранит его ленточку\nна память о ветреном дне.","Повітряний змій із душею хмари.\nМіка береже його стрічку\nна згадку про вітряний день."}},
            {"fern_compass",new[]{"A compass from the forest.\nIts little fern points toward\nplaces Mika has not met yet.","Лесной компас.\nЕго маленький папоротник зовёт\nв места, где Мика ещё не была.","Лісовий компас.\nЙого маленька папороть кличе\nтуди, де Міка ще не бувала."}},
            {"amber_wing",new[]{"A wing that remembers summer.\nMika wears it when she wants\nto hear the warm garden again.","Крылышко, хранящее лето.\nМика надевает его, чтобы снова\nуслышать тёплый сад.","Крильце, що береже літо.\nМіка вдягає його, щоб знову\nпочути теплий сад."}},
            {"moon_boat",new[]{"A boat for moonlit dreams.\nIt sails across Mika’s pocket\ntoward a very quiet shore.","Лодочка для лунных снов.\nОна плывёт по карману Мики\nк самому тихому берегу.","Човник для місячних снів.\nВін пливе кишенею Міки\nдо найтихішого берега."}},
            {"petal_drift",new[]{"A hello from the garden.\nPetals catch the little gusts\nand dance between the islands.","Привет из сада.\nЛепестки ловят порывы ветра\nи танцуют между островами.","Привіт із саду.\nПелюстки ловлять подихи вітру\nй танцюють між островами."}},
            {"firefly_dance",new[]{"An evening full of little lights.\nThe fireflies meet Mika\nas if they have been expecting her.","Вечер маленьких огоньков.\nСветлячки встречают Мику так,\nбудто давно её ждали.","Вечір маленьких вогників.\nСвітлячки зустрічають Міку так,\nначе давно на неї чекали."}},
            {"butterfly_garden",new[]{"A garden in the sky.\nButterflies follow the breeze\nand carry a little spring along.","Сад в небе.\nБабочки летят вслед за ветром\nи несут с собой немного весны.","Сад у небі.\nМетелики летять слідом за вітром\nі несуть із собою трохи весни."}},
            {"swallow_flock",new[]{"A visit from travelling friends.\nSwallows draw gentle arcs\naround the distant islands.","В гости к друзьям.\nЛасточки рисуют плавные дуги\nвокруг далёких островов.","У гості до друзів.\nЛастівки малюють плавні дуги\nнавколо далеких островів."}},
            {"dragonfly_stream",new[]{"A little summer patrol.\nDragonflies inspect the sky\nand pause to say hello to Mika.","Маленький летний дозор.\nСтрекозы осматривают небо\nи здороваются с Микой на лету.","Маленька літня варта.\nБабки оглядають небо\nй вітаються з Мікою на льоту."}},
            {"lantern_flight",new[]{"Letters made of warm light.\nSlow lanterns drift past\nwith good wishes from far away.","Письма из тёплого света.\nФонарики неспешно плывут мимо\nс добрыми пожеланиями издалека.","Листи з теплого світла.\nЛіхтарики неквапно пливуть повз\nіз добрими побажаннями здалеку."}},
            {"snow_wings",new[]{"A quiet winter visit.\nSnowflakes and little birds\nshare the soft sky with Mika.","Тихий зимний визит.\nСнежинки и маленькие птицы\nделят с Микой мягкое небо.","Тихий зимовий візит.\nСніжинки й маленькі птахи\nділять із Мікою лагідне небо."}},
            {"comet_trails",new[]{"A trail of bedtime stories.\nLittle stars cross the sky\nwhile moon moths follow quietly.","Дорожка вечерних сказок.\nЗвёздочки пересекают небо,\nа лунные мотыльки летят следом.","Стежка вечірніх казок.\nЗірочки перетинають небо,\nа місячні метелики летять слідом."}},
            {"ribbon_kites",new[]{"A message to the wind.\nBright kites trail their ribbons\nlike cheerful little signatures.","Послание ветру.\nВоздушные змеи тянут ленточки,\nсловно ставят весёлые подписи.","Послання вітрові.\nПовітряні змії тягнуть стрічки,\nначе ставлять веселі підписи."}},
            {"origami_cranes",new[]{"Paper wings, a real journey.\nThe breeze carries tiny cranes\nfrom one daydream to the next.","Бумажные крылья, настоящий путь.\nВетер переносит журавликов\nиз одной мечты в другую.","Паперові крила, справжній шлях.\nВітер переносить журавликів\nз однієї мрії до іншої."}},
            {"bubble_dream",new[]{"Dreams with round windows.\nPearl bubbles rise gently\nand borrow the colours of the sky.","Мечты с круглыми окошками.\nПерламутровые пузыри всплывают\nи примеряют цвета неба.","Мрії з круглими віконцями.\nПерламутрові бульбашки спливають\nі приміряють барви неба."}},
            {"aurora_veil",new[]{"A curtain woven by the night.\nSoft ribbons of light unfold\nabove Mika’s little journey.","Занавес, сотканный ночью.\nМягкие световые ленты раскрываются\nнад маленьким путешествием Мики.","Завіса, виткана ніччю.\nМ’які світлові стрічки розгортаються\nнад маленькою мандрівкою Міки."}},
            {"garden_frame",new[]{"A window into the garden.\nLeaves gather at the edges\nso Mika can carry spring along.","Окошко в сад.\nЛистья собираются по краям,\nчтобы Мика брала весну с собой.","Віконце в сад.\nЛистя збирається по краях,\nщоб Міка брала весну із собою."}},
            {"sky_frame",new[]{"A window into the clouds.\nA few soft feathers frame\nMika’s next bright discovery.","Окошко в облака.\nНежные перья обрамляют\nследующее открытие Мики.","Віконце у хмари.\nНіжні пір’їнки обрамляють\nнаступне відкриття Міки."}},
            {"copper_frame",new[]{"A keepsake of the workshop.\nWarm copper holds the picture\nlike a frame made by a friend.","Память о мастерской.\nТёплая медь держит картину,\nсловно рамка, сделанная другом.","Згадка про майстерню.\nТепла мідь тримає картину,\nначе рамка, зроблена другом."}},
            {"lunar_frame",new[]{"A window for quiet wishes.\nMoonlight settles at the edges\nand keeps Mika’s story company.","Окошко для тихих желаний.\nЛунный свет ложится по краям\nи слушает историю Мики.","Віконце для тихих бажань.\nМісячне світло лягає по краях\nй слухає історію Міки."}},
        };
        UiCopy ReferenceTrophyDescription(string id)
        {
            return collectionStories.TryGetValue(id,out var words)?ReferenceCopy(words[0],words[1],words[2]):TrophyBenefit(id);
        }
    }
}
